class C:
 @staticmethod
 def s(): return 7
 @classmethod
 def c(cls): return cls
 @property
 def p(self): return 9
d=C.__dict__
print(d["s"].__func__ is C.s,d["c"].__func__ is C.c.__func__,d["p"].fget(C()))

class C: pass
p=C.__dict__
try: p.tag=7
except AttributeError: print("readonly")
try: del p.tag
except AttributeError: print("readonly")

class M(type):
 def __getattribute__(cls,name):
  if name=="__dict__": return [7]
  return type.__getattribute__(cls,name)
class C(metaclass=M): tag=9
print(C.__dict__[0],vars(C)[0],type.__getattribute__(C,"__dict__")["tag"])

class M(type):
 @property
 def __dict__(cls): return [7]
class C(metaclass=M): tag=9
print(C.__dict__[0],vars(C)[0],type.__getattribute__(C,"__dict__")[0])

class M(type):
 @property
 def __dict__(cls): raise ValueError("lookup")
class C(metaclass=M): pass
vars(C)

class C: tag=7
class Key:
 def __hash__(self): return hash("tag")
 def __eq__(self,other): return True
print(C.__dict__[Key()])

class M(type):
 def __setattr__(cls,name,value): print("set",name)
 def __delattr__(cls,name): print("delete",name)
class C(metaclass=M): tag=7
C.__dict__={}
del C.__dict__
print(C.__dict__["tag"])

class C: pass
try: type.__setattr__(C,"__dict__",{})
except AttributeError: print("set")
try: type.__delattr__(C,"__dict__")
except AttributeError: print("delete")
